import{c as s,Q as i,j as a,m as t}from"./chunks/framework.DGHXLY8X.js";const k=JSON.parse('{"title":"Installing VideoNode","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md","lastUpdated":1780259307000}'),n={name:"getting-started/installation.md"};function o(l,e,d,h,r,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="installing-videonode" tabindex="-1">Installing VideoNode <a class="header-anchor" href="#installing-videonode" aria-label="Permalink to &quot;Installing VideoNode&quot;">​</a></h1><p>VideoNode is distributed as a Debian package for Linux arm64. This page covers installing it from the APT repository on an RK3588-based board running a Debian-compatible OS with V4L2 capture support.</p><p><strong>Prerequisites:</strong></p><ul><li>Linux, arm64 (aarch64). VideoNode targets Rockchip RK3588 SBCs for hardware encoding. The recommended board is the <a href="https://www.friendlyelec.com/index.php?route=product/product&amp;product_id=292" target="_blank" rel="noreferrer">FriendlyElec NanoPC-T6</a> (8GB / 64GB eMMC or higher); other RK3588 boards work but the encoder paths are tuned and validated against the T6.</li><li>Debian 13 (trixie) or newer. The native binaries link trixie-era shared libraries (<code>libplacebo349</code>, <code>libabsl20240722</code>, and the <code>t64</code> builds of gRPC and protobuf), so <code>apt</code> refuses to install VideoNode on bookworm or older with a <code>base-files (&gt;= 13~)</code> dependency error. Upgrade the board&#39;s OS to trixie first if it is still on bookworm.</li><li>A V4L2-capable capture device (e.g. <code>/dev/video0</code>): USB or MIPI-CSI cameras, HDMI capture cards. Verify with <code>v4l2-ctl --list-devices</code>.</li><li><code>curl</code>, <code>gpg</code>, and <code>apt</code> available</li><li>A Linux account with <code>sudo</code> for the install steps below</li></ul><h2 id="install-required-runtime-dependencies" tabindex="-1">Install required runtime dependencies <a class="header-anchor" href="#install-required-runtime-dependencies" aria-label="Permalink to &quot;Install required runtime dependencies&quot;">​</a></h2><h3 id="ffmpeg-with-h264-rkmpp" tabindex="-1">ffmpeg with <code>h264_rkmpp</code> <a class="header-anchor" href="#ffmpeg-with-h264-rkmpp" aria-label="Permalink to &quot;ffmpeg with \`h264_rkmpp\`&quot;">​</a></h3><p>The daemon shells out to <code>ffmpeg</code> from <code>PATH</code>. On a Rockchip board you need a build with <code>h264_rkmpp</code> and <code>hevc_rkmpp</code> enabled; stock Debian&#39;s <code>ffmpeg</code> does not include them. Use the ffmpeg that ships with your board&#39;s vendor OS image if it advertises Rockchip support, or install a community build like <a href="https://github.com/nyanmisaka/ffmpeg-rockchip" target="_blank" rel="noreferrer">nyanmisaka/ffmpeg-rockchip</a>. Confirm with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffmpeg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -encoders</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rkmpp</span></span></code></pre></div><p>After install, run <code>videonode validate-encoders</code> to verify the probe finds the hardware encoder. See <a href="./../operating/encoders">Encoders</a> for the precedence rules and example output.</p><h3 id="rockchip-userspace-libraries-rga-mpp" tabindex="-1">Rockchip userspace libraries (RGA + MPP) <a class="header-anchor" href="#rockchip-userspace-libraries-rga-mpp" aria-label="Permalink to &quot;Rockchip userspace libraries (RGA + MPP)&quot;">​</a></h3><p>The native binaries dynamically link <code>librga</code> and <code>librockchip-mpp</code>. VideoNode&#39;s CI builds against pinned releases from <a href="https://github.com/tsukumijima/mpp-rockchip" target="_blank" rel="noreferrer">tsukumijima/mpp-rockchip</a> and <a href="https://github.com/tsukumijima/librga-rockchip" target="_blank" rel="noreferrer">tsukumijima/librga-rockchip</a>. Install matching <code>.deb</code> files from those release pages, or use the equivalents your vendor OS provides. The MPP kernel module must also be loaded (<code>/proc/mpp_service/load</code> must exist); vendor images for the NanoPC-T6 load it by default.</p><h2 id="enable-device-tree-overlays-gpu-hdmi-input" tabindex="-1">Enable device-tree overlays (GPU + HDMI input) <a class="header-anchor" href="#enable-device-tree-overlays-gpu-hdmi-input" aria-label="Permalink to &quot;Enable device-tree overlays (GPU + HDMI input)&quot;">​</a></h2><p>The composer GPU-composites onto a canvas using the Mali GPU, which is only usable when the kernel binds it through the <strong><code>panthor</code></strong> driver. <code>panthor</code> creates a DRM render node under <code>/dev/dri/</code> (e.g. <code>renderD130</code>). If that node is missing, the composer cannot initialize and logs errors like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>egl_ctx: open(/dev/dri/renderD130): No such file or directory</span></span>
<span class="line"><span>pl_compose: both Vulkan and OpenGL backends failed</span></span>
<span class="line"><span>canvas_loop: pl_compose init 1920x1080 failed</span></span></code></pre></div><p>On Armbian/RK3588 the GPU is enabled by a <strong>device-tree overlay</strong>. Capturing from the onboard HDMI-RX port needs a second overlay.</p><p>Edit <code>/boot/armbianEnv.txt</code> and add both overlays to the <code>overlays=</code> line:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># /boot/armbianEnv.txt</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">overlay_prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=rockchip-rk3588</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">overlays</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=panthor-gpu rk3588-hdmirx</span></span></code></pre></div><ul><li><code>panthor-gpu</code>: binds the Mali GPU to the <code>panthor</code> driver (required for the composer). With <code>overlay_prefix=rockchip-rk3588</code> it resolves to <code>/boot/dtb/rockchip/overlay/rockchip-rk3588-panthor-gpu.dtbo</code>.</li><li><code>rk3588-hdmirx</code>: enables the HDMI-RX capture input (only needed if you capture from the onboard HDMI-in port).</li></ul><p>The same overlays can be toggled from a menu with <code>sudo armbian-config</code> (System → Hardware). GPU compositing also benefits from a larger CMA pool; if the canvas fails to allocate, raise it on the kernel cmdline in the same file:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extraargs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cma</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1G</span></span></code></pre></div><p>Reboot to apply, then confirm a render node is bound to <code>panthor</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># after reboot:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> n </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/class/drm/renderD*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">basename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;) -&gt; $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">basename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">readlink</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/device/driver&quot;)&quot;)&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span></span></code></pre></div><p>You should see a line ending in <code>-&gt; panthor</code> alongside <code>rockchip-drm</code> and <code>RKNPU</code>. If no <code>panthor</code> node appears, re-check the <code>overlays=</code> line and that the board booted a trixie-based image.</p><h2 id="install-from-the-apt-repository" tabindex="-1">Install from the APT repository <a class="header-anchor" href="#install-from-the-apt-repository" aria-label="Permalink to &quot;Install from the APT repository&quot;">​</a></h2><p>Follow these steps in order.</p><ol><li><p>To trust the repository&#39;s signing key, download and install it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://mazurov.dev/videonode/public.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> gpg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dearmor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/share/keyrings/videonode-archive-keyring.gpg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span></span></code></pre></div></li><li><p>To add the repository to your APT sources, write the sources entry:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;deb [arch=arm64 signed-by=/usr/share/keyrings/videonode-archive-keyring.gpg] </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://mazurov.dev/videonode stable main&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/apt/sources.list.d/videonode.list</span></span></code></pre></div></li><li><p>To fetch the updated package index, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div></li><li><p>To install VideoNode, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode</span></span></code></pre></div></li></ol><p>The post-install script creates a <code>videonode</code> system user, writes default configuration to <code>/etc/videonode/config.toml</code>, enables <code>videonode.service</code>, and starts it immediately.</p><h2 id="web-ui-authentication" tabindex="-1">Web UI authentication <a class="header-anchor" href="#web-ui-authentication" aria-label="Permalink to &quot;Web UI authentication&quot;">​</a></h2><p>VideoNode authenticates web UI logins against the Linux user database (<code>/etc/shadow</code>). Two things must be true for a user to log in:</p><ol><li>The user has a regular Linux account on the box.</li><li>The user is a member of the <code>videonode</code> group.</li></ol><p>If you ran <code>apt install</code> with <code>sudo</code>, the postinst script enrolls <code>$SUDO_USER</code> into the <code>videonode</code> group automatically. Log in to the UI with your usual username and password. Otherwise, add yourself manually:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adduser</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode</span></span></code></pre></div><p>You&#39;ll need to log out and back in (or run <code>newgrp videonode</code>) for the new group membership to take effect for new shells. The daemon itself has read access to <code>/etc/shadow</code> via its membership in the <code>shadow</code> group, granted automatically at install time.</p><p>To add another operator later, run the same <code>adduser ... videonode</code> command for their account.</p><h3 id="bypassing-linux-auth-basic-credentials" tabindex="-1">Bypassing Linux auth (basic credentials) <a class="header-anchor" href="#bypassing-linux-auth-basic-credentials" aria-label="Permalink to &quot;Bypassing Linux auth (basic credentials)&quot;">​</a></h3><p>If you&#39;d rather skip the Linux account / group setup entirely (for example on a single-user box, or during initial bring-up), switch the daemon to basic auth. Edit <code>/etc/videonode/config.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;basic&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">username = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">password = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;change-me&quot;</span></span></code></pre></div><p>Then <code>sudo systemctl restart videonode</code>. Log in with the username and password from the file. <strong>Change the defaults before exposing the daemon to a network</strong>: basic auth ships passwords in cleartext over HTTP unless you terminate TLS upstream.</p><p>For the full list of <code>[auth]</code> and other settings, see <a href="./../reference/config-toml#auth">config.toml reference</a>.</p><h2 id="verify-the-service-is-running" tabindex="-1">Verify the service is running <a class="header-anchor" href="#verify-the-service-is-running" aria-label="Permalink to &quot;Verify the service is running&quot;">​</a></h2><p>To confirm the service started, check its status:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode.service</span></span></code></pre></div><p>To follow live logs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>The API is available at <code>http://localhost:8090</code> once the service is up. See the <a href="./quickstart">quickstart</a> for first steps after installation.</p>`,45)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
